  // performance statistics from the NAV history (daily), optionally against a benchmark price series
  function perfStats(navHist, bench, policyRate) {
    const navs = navHist.map(x => Number(x.nav)).filter(v => v > 0); if (navs.length < 2) return null;
    const rets = navs.slice(1).map((v, i) => v / navs[i] - 1);
    const mean = rets.reduce((a, b) => a + b, 0) / rets.length; const vol = Math.sqrt(rets.reduce((a, r) => a + (r - mean) ** 2, 0) / Math.max(1, rets.length - 1)) * Math.sqrt(252);
    let peak = navs[0], mdd = 0; navs.forEach(v => { peak = Math.max(peak, v); mdd = Math.min(mdd, v / peak - 1); });
    const total = navs[navs.length - 1] / navs[0] - 1; const years = rets.length / 252; const ann = years > 0 ? Math.pow(1 + total, 1 / Math.max(years, 1 / 252)) - 1 : 0;
    const rf = policyRate || 0; const sharpe = vol ? (ann - rf) / vol : 0;
    const neg = rets.filter(r => r < 0); const dvol = Math.sqrt(neg.reduce((a, r) => a + r * r, 0) / Math.max(1, rets.length)) * Math.sqrt(252); const sortino = dvol ? (ann - rf) / dvol : 0;
    const wins = rets.filter(r => r > 0).length / rets.length;
    let benchTotal = null, beta = null, alpha = null, corr = null;
    if (bench && bench.length >= navs.length) {
      const b = bench.slice(-navs.length); const br = b.slice(1).map((v, i) => v / b[i] - 1);
      benchTotal = b[b.length - 1] / b[0] - 1; const bm = br.reduce((a, x) => a + x, 0) / br.length;
      const cov = rets.reduce((a, r, i) => a + (r - mean) * (br[i] - bm), 0) / Math.max(1, rets.length - 1); const bvar = br.reduce((a, x) => a + (x - bm) ** 2, 0) / Math.max(1, br.length - 1);
      beta = bvar ? cov / bvar : 0; corr = (bvar && vol) ? cov / Math.sqrt(bvar) / (vol / Math.sqrt(252)) : 0; alpha = ann - (rf + beta * (Math.pow(1 + benchTotal, 1 / Math.max(years, 1 / 252)) - 1 - rf));
    }
    return { days: rets.length, total, ann, vol, sharpe, sortino, mdd, wins, best: Math.max(...rets), worst: Math.min(...rets), benchTotal, beta, alpha, corr };
  }


