    const stBody = () => ({ strategy_type: $('#stType').value.replace(/ /g, '_'), underlying: under, expiry: $('#stExp').value.trim(), expiry2: $('#stExp2').value || null, strikes: $('#stStrikes').value.split(',').map(s => +s.trim()).filter(x => x), quantity: +$('#stQty').value, net_limit: $('#stLimit').value ? +$('#stLimit').value : null, time_in_force: $('#stTif').value });
    const analyticsHtml = a => `<div class="kv"><div>Net per unit</div><div>${fmt.signed(a.net_premium_per_unit)} <span class="muted">(+ debit / − credit)</span></div><div>Max gain</div><div>${a.max_gain == null ? 'unlimited' : fmt.signed(a.max_gain)}</div><div>Max loss</div><div>${a.max_loss == null ? 'unlimited' : fmt.signed(a.max_loss)}</div><div>Breakevens</div><div>${(a.breakevens || []).map(b => fmt.px(b)).join(', ') || '—'}</div><div>Δ / Γ / vega / Θ</div><div>${GK(a.greeks.delta)} / ${GK(a.greeks.gamma, 2)} / ${GK(a.greeks.vega)} / ${GK(a.greeks.theta)}</div>${a.incremental_margin != null ? `<div>Incremental margin</div><div>${fmt.money(a.incremental_margin)}</div>` : ''}${a.needs_shares ? `<div>Requires shares</div><div>${fmt.qty(a.needs_shares)}</div>` : ''}</div>${a.legs ? `<table style="margin-top:6px"><tr><th>Leg</th><th>Bid</th><th>Ask</th><th>IV</th><th>Δ</th></tr>${a.legs.map(l => `<tr><td class="l">${l.side === 'BUY' ? '+' : '−'}${l.quantity} ${esc(optName(l.security_id))}</td><td>${fmt.px(l.quote.bid)}</td><td>${fmt.px(l.quote.ask)}</td><td>${fmt.pct(l.quote.iv, 1)}</td><td>${l.quote.delta.toFixed(3)}</td></tr>`).join('')}</table>` : ''}${a.payoff ? '<canvas id="payoff" style="margin-top:8px"></canvas>' : ''}`;
