  const fmtLevel = (p, v) => v == null ? '—' : (['CAP', 'FLOOR', 'SWAPTION', 'EQUITY_OPTION', 'FX_OPTION', 'BARRIER_OPTION', 'DIGITAL_OPTION', 'ASIAN_OPTION'].includes(p) ? fmt.money(v) : ['COMMODITY_SWAP', 'EQUITY_FORWARD', 'COMMODITY_FORWARD', 'FX_FORWARD', 'NDF', 'FX_SWAP', 'DIVIDEND_SWAP'].includes(p) ? Number(v).toFixed(4) : ['IRS', 'OIS', 'FRA', 'INFLATION_SWAP'].includes(p) ? (Number(v) / 100).toFixed(3) + '%' : ['VARIANCE_SWAP', 'VOL_SWAP'].includes(p) ? Number(v).toFixed(2) + ' vol' : ['PPN', 'REVERSE_CONVERTIBLE', 'AUTOCALLABLE'].includes(p) ? Number(v).toFixed(2) + '% of par' : p === 'CRYPTO_PERP' ? fmt.px(v) : Number(v).toFixed(2) + 'bp');
