      const id = b.dataset.rp, act = b.dataset.act; let body = {};
      if (act === 'collateral') { const sec = prompt('Additional collateral security id (eligible, unencumbered):', 'UST-5Y'); const q = prompt('Face to pledge:', '5000000'); if (!sec || !q) return; body = { security_id: sec, quantity: +q }; }
      if (act === 'cash') { const a = prompt('Cash margin to post:', '1000000'); if (!a) return; body = { amount: +a }; }
      if (act === 'reduce') { const a = prompt('Principal to repay:', '1000000'); if (!a) return; body = { amount: +a }; }
      if (act === 'substitute') { const o = prompt('Release security id:'); const oq = prompt('Release face:'); const n = prompt('Replacement security id:'); const nq = prompt('Replacement face:'); if (!o || !oq || !n || !nq) return; body = { old_security_id: o, old_quantity: +oq, new_security_id: n, new_quantity: +nq }; }
