  const pageCollateral = async () => {
    const d = await api(P() + '/collateral'); const pb = d.prime;
    $('#main').innerHTML = `<h1>COLLATERAL <small>shared across securities lending, repo and prime brokerage · regime haircut multiplier ${d.regime_haircut_multiplier}x</small></h1>
      <div class="tiles">${tile('Cash unencumbered', fmt.money(d.cash_unencumbered))}${tile('Available collateral value', fmt.money(d.available_collateral_value_repo), 'repo haircuts, unencumbered assets + cash')}${tile('Posted — sec lending', fmt.money(d.cash_collateral_posted.SECLOAN + d.securities_collateral_posted.SECLOAN))}${tile('Posted — repo', fmt.money(d.securities_collateral_posted.REPO + d.cash_collateral_posted.REPO))}${tile('Received — reverse repo', fmt.money(d.received.REVERSE_REPO))}${tile('Treasury encumbrance', fmt.pct(d.treasury_encumbrance_pct, 0))}${tile('Calls open', d.calls.filter(c => c.status === 'OPEN').length, fmt.money(d.calls.filter(c => c.status === 'OPEN').reduce((a, c) => a + c.amount, 0)) + ' due')}</div>
      <div class="grid2" style="margin-top:14px"><div class="panel"><h2 style="margin-top:0">Available collateral</h2><div class="scroll"><table><tr><th>Security</th><th>Class</th><th>Settled</th><th>Pledged</th><th>Pend. deliver</th><th>Available</th><th>MV available</th><th>Haircut repo / PB</th><th>Value repo / PB</th></tr>${d.available.map(r => `<tr class="click" data-href="#/position/${r.security_id}"><td><b>${r.security_id}</b></td><td class="l">${r.asset_key}</td><td>${fmt.qty(r.settled)}</td><td>${fmt.qty(r.pledged)}</td><td>${fmt.qty(r.pending_deliver)}</td><td>${fmt.qty(r.available)}</td><td>${fmt.money(r.market_value_available)}</td><td>${r.haircuts.REPO == null ? '—' : fmt.pct(r.haircuts.REPO, 1)} / ${r.haircuts.PRIME == null ? '—' : fmt.pct(r.haircuts.PRIME, 1)}</td><td>${fmt.money(r.collateral_value.REPO)} / ${fmt.money(r.collateral_value.PRIME)}</td></tr>`).join('') || '<tr><td colspan=9 class="muted">no securities</td></tr>'}</table></div>
        <h2>Encumbered assets</h2><table><tr><th>Security</th><th>Qty</th><th>Purpose</th><th>Reference</th><th>MV</th></tr>${d.encumbered.map(e => `<tr><td>${e.security_id}</td><td>${fmt.qty(e.quantity)}</td><td class="l">${e.purpose}</td><td>${e.reference}</td><td>${fmt.money(e.market_value)}</td></tr>`).join('') || '<tr><td colspan=5 class="muted">nothing pledged</td></tr>'}</table></div>
        <div class="panel"><h2 style="margin-top:0">Margin & collateral calls <small>hover a row for the reason</small></h2><table><tr><th>Call</th><th>Source</th><th>Reference</th><th>Amount</th><th>Issued</th><th>Due</th><th>Status</th></tr>${d.calls.map(c => `<tr title="${esc(c.reason)}"><td>${c.id}</td><td class="l">${c.source}</td><td>${c.reference}</td><td>${fmt.money(c.amount)}</td><td>${c.issued}</td><td>${c.due}</td><td>${statusBadge(c.status)}</td></tr>`).join('') || '<tr><td colspan=7 class="muted">none</td></tr>'}</table>${d.calls.filter(c => c.status === 'OPEN').map(c => `<div class="hint"><b>${c.id}</b>: ${esc(c.reason)}</div>`).join('')}
        <h2>Prime brokerage financing <small>${esc(pb.broker)}</small></h2><div class="kv"><div>Margin loan</div><div>${fmt.money(pb.loan_balance)} @ ${fmt.pct(pb.rate)}</div><div>Accrued interest</div><div>${fmt.money(pb.accrued_interest)}</div><div>Collateral value (financing haircuts)</div><div>${fmt.money(pb.collateral_value)} <span class="muted">incl. cash ${fmt.money(pb.cash_component)}</span></div><div>Short requirement (30% of short MV)</div><div>${fmt.money(pb.short_requirement)}</div><div>Requirement</div><div>${fmt.money(pb.requirement)}</div><div><b>Excess liquidity</b></div><div class="${pb.excess_liquidity < 0 ? 'neg' : 'pos'}"><b>${fmt.money(pb.excess_liquidity)}</b></div></div>
        <div class="row" style="margin-top:8px"><input id="pbAmt" type="number" value="1000000" style="width:160px"><button class="btn" id="pbDraw">Draw</button><button class="btn" id="pbRepay">Repay</button><span class="error" id="pbDrawErr"></span><span class="error" id="pbRepayErr"></span></div>
        <p class="hint">Shortfalls in settled cash are drawn automatically; idle cash repays automatically. A negative excess raises a margin call due next cycle; a second unmet cycle triggers liquidation of futures then unencumbered longs through ordinary forced trades.</p>
        <h2>Financing collateral by position</h2><div class="scroll"><table><tr><th>Security</th><th>Available</th><th>MV</th><th>Haircut</th><th>Financing value</th></tr>${pb.rows.map(r => `<tr><td>${r.security_id}</td><td>${fmt.qty(r.available)}</td><td>${fmt.money(r.market_value)}</td><td>${r.haircut == null ? 'ineligible' : fmt.pct(r.haircut, 1)}</td><td>${fmt.money(r.collateral_value)}</td></tr>`).join('')}</table></div></div></div>`;
    bindAction('pbDraw', async () => { await post(P() + '/margin/draw', { amount: +$('#pbAmt').value }); });
    bindAction('pbRepay', async () => { await post(P() + '/margin/repay', { amount: +$('#pbAmt').value }); });
    bindRows();
  };

  const pageCareer = async () => {
    const c = await api(P() + '/career'); const j = c.job; const m = c.metrics; const ls = c.limits_status;
    const lim = (l, f) => l.limit == null || l.limit >= 9 ? `${f(l.value)} <span class="muted">/ no limit</span>` : `<span class="${l.value > l.limit ? 'neg' : ''}">${f(l.value)}</span> / ${f(l.limit)}`;
    $('#main').innerHTML = `<h1>CAREER <small>${esc(j.title)} · ${esc(c.level_title)} (level ${c.level + 1} of ${j.ladder.length})</small></h1>
      <p class="hint">${esc(j.description)} Mandate: ${j.allowed_classes.join(', ')}. Benchmark: ${j.benchmark || 'absolute return over cash'}.</p>
      <div class="tiles">${tile('Return since inception', fmt.pct(m.return_since_inception), m.benchmark_return != null ? `benchmark ${fmt.pct(m.benchmark_return)} · alpha ${fmt.pct(m.alpha)}` : `${m.days} days`)}${tile('Sharpe', m.sharpe.toFixed(2), `vol ${fmt.pct(m.volatility, 1)}`)}${tile('Max drawdown', fmt.pct(m.max_drawdown, 1), `current ${fmt.pct(m.current_drawdown, 1)}`)}${tile('Gross leverage', lim(ls.gross_leverage, v => v.toFixed(2) + 'x'), 'limit')}${tile('Largest position', lim(ls.max_position, v => fmt.pct(v, 1)), 'of NAV / limit')}${tile('Drawdown limit', lim(ls.drawdown, v => fmt.pct(v, 1)), 'from peak / limit')}${tile('Capital allocated', fmt.money(c.contributed_capital))}</div>
      <p class="hint">Ladder: ${j.ladder.map((t, i) => i === c.level ? `<b style="color:var(--accent)">${t}</b>` : t).join(' → ')}. Promotion after an EXCEEDS quarterly review; two UNACCEPTABLE quarters demote.</p>
      ${c.missions && c.missions.length ? `<div class="panel"><h2 style="margin-top:0">Missions</h2><table><tr><th>Mission</th><th>Progress</th><th>Deadline</th><th>Status</th></tr>${c.missions.map(ms => `<tr><td class="l" style="white-space:normal"><b>${esc(ms.title)}</b><br><span class="muted">${esc(ms.description)}</span></td><td><div class="bar"><i style="width:${Math.round(ms.progress * 100)}%"></i></div>${Math.round(ms.progress * 100)}%</td><td>${ms.deadline}</td><td><span class="badge ${ms.status === 'COMPLETED' ? 'green' : ms.status === 'FAILED' ? 'red' : 'amber'}">${ms.status}</span>${ms.bonus ? ` <span class="muted">bonus ${fmt.money(ms.bonus, 0)}</span>` : ''}</td></tr>`).join('')}</table><p class="hint">Missions are the job's proficiency tests: each completed mission earns a 5% capital allocation. They are checked at every close from the portfolio's actual state.</p></div>` : ''}
      ${c.scenario && c.scenario !== 'NONE' ? `<div class="panel"><h2 style="margin-top:0">Scenario: ${esc(c.scenario)}</h2>${c.scenario_log.length ? c.scenario_log.map(x => `<div><span class="muted">${x.date}</span> <span class="badge red">day ${x.day}</span> ${esc(x.note)}</div>`).join('') : '<span class="muted">the script has not started yet</span>'}</div>` : ''}
      <div class="grid2" style="margin-top:14px"><div class="panel"><h2 style="margin-top:0">Performance reviews</h2>${c.reviews.length ? c.reviews.map(r => `<div style="margin-bottom:12px"><div><span class="badge ${r.rating === 'EXCEEDS' ? 'green' : r.rating === 'MEETS' ? 'blue' : 'red'}">${r.rating}</span> <b>${r.period} ${r.start} → ${r.end}</b> <span class="muted">${esc(r.title)}</span></div><div class="kv" style="margin-top:4px"><div>Return</div><div>${fmt.pct(r.return)} ${r.benchmark_return != null ? `vs benchmark ${fmt.pct(r.benchmark_return)} · alpha ${fmt.pct(r.alpha)}` : ''}</div><div>P&L</div><div>${fmt.signed(r.pnl)}</div><div>Max drawdown / Sharpe</div><div>${fmt.pct(r.max_drawdown, 1)} / ${r.sharpe.toFixed(2)}</div><div>Largest contribution</div><div>${r.largest_contribution.security_id || '—'} ${fmt.signed(r.largest_contribution.pnl)}</div><div>Largest loss</div><div>${r.largest_loss.security_id || '—'} ${fmt.signed(r.largest_loss.pnl)}</div><div>By bucket</div><div>${Object.entries(r.buckets).filter(([k, v]) => v).map(([k, v]) => `${BUCKET_LABEL[k] || k} ${fmt.signed(v)}`).join(' · ')}</div><div>Breaches / fails / calls missed</div><div>${r.risk_breaches} / ${r.settlement_failures} / ${r.margin_calls_missed}</div></div><div class="muted" style="margin-top:4px">${esc(r.evaluation)}</div></div>`).join('') : '<span class="muted mono">first review at month end</span>'}</div>
        <div class="panel"><h2 style="margin-top:0">Career log</h2>${c.career_log.length ? c.career_log.map(x => `<div><span class="muted">${x.date}</span> <span class="badge ${x.kind === 'PROMOTION' ? 'green' : 'red'}">${x.kind}</span> ${esc(x.text)}</div>`).join('') : '<span class="muted mono">no events yet</span>'}
          <h2>Risk-limit breaches</h2><div class="scroll"><table><tr><th>Date</th><th>Kind</th><th>Detail</th></tr>${c.breaches.map(b => `<tr><td>${b.date}</td><td class="l">${b.kind}</td><td class="l" style="white-space:normal">${esc(b.text)}</td></tr>`).join('') || '<tr><td colspan=3 class="muted">none</td></tr>'}</table></div>
          <h2>Margin calls</h2><table><tr><th>Date</th><th>ID</th><th>Amount</th><th>Status</th><th>Reason</th></tr>${c.margin_calls.map(x => `<tr><td>${x.date}</td><td>${x.id}</td><td>${fmt.money(x.amount)}</td><td>${statusBadge(x.status)}</td><td class="l" style="white-space:normal">${esc(x.reason)}</td></tr>`).join('') || '<tr><td colspan=5 class="muted">none</td></tr>'}</table></div></div>`;
  };

  // ---------------------------------------------------------------- my desk (phase 8/10): the job's own book
  const pageDesk = async () => {
    const d = await api(P() + '/desk');
    const parts = [];
    if (d.investors) { const v = d.investors; parts.push(`<div class="panel"><h2 style="margin-top:0">Investors</h2><div class="tiles">${tile('Subscribed capital', fmt.money(v.total_subscribed, 0))}${tile('High-water mark', fmt.money(v.high_water_mark, 0))}${tile('Management fee accrued', fmt.money(v.mgmt_fee_accrued, 0), `${fmt.pct(v.mgmt_fee, 1)} p.a., paid monthly`)}${tile('Fees paid to date', fmt.money(v.fees_paid, 0), `${fmt.pct(v.perf_fee, 0)} performance fee over the HWM, crystallised in December`)}</div>
      <div class="grid2"><div><h2>Holders</h2><table><tr><th>Investor</th><th>Capital</th></tr>${Object.entries(v.investors).map(([k, a]) => `<tr><td class="l">${esc(k)}</td><td>${fmt.money(a, 0)}</td></tr>`).join('')}</table></div>
      <div><h2>Pending dealing</h2><table><tr><th>Investor</th><th>Kind</th><th>Amount</th><th>Dealing day</th></tr>${v.pending.map(p => `<tr><td class="l">${esc(p.investor)}</td><td>${p.kind}</td><td>${fmt.money(p.amount, 0)}</td><td>${p.dealing}</td></tr>`).join('') || '<tr><td colspan=4 class="muted">none notified</td></tr>'}</table></div></div>
      <h2>Flows</h2><div class="scroll"><table>${v.flows.slice().reverse().map(f => `<tr><td>${f.date}</td><td class="l">${f.kind}</td><td class="l" style="white-space:normal">${esc(f.detail)}</td></tr>`).join('') || '<tr><td class="muted">none yet</td></tr>'}</table></div>
      <p class="hint">Investors watch trailing returns, drawdown and risk breaches. Redemptions are notified on the 15th and paid at month end; subscriptions arrive after strong quarters. Fees leave the fund: NAV net of fees is what investors judge you on.</p></div>`); }
    if (d.clients) { const c = d.clients; const st = c.stats || {};
      const fmtParams = p => Object.entries(p || {}).map(([k, v]) => `${k.replace(/_/g, ' ')} ${typeof v === 'number' ? (Math.abs(v) >= 1000 ? fmt.qty(v) : v) : v}`).join(' · ');
      const lvl = r => r.level == null ? '—' : (r.unit && r.unit.startsWith('price') ? fmt.px(r.level) : r.unit === 'bp' || (r.unit || '').includes('bp') ? Number(r.level).toFixed(2) + 'bp' : fmt.money(r.level));
      parts.push(`<div class="panel"><h2 style="margin-top:0">Client requests</h2><div class="tiles">${tile('Won / lost', `${st.won || 0} / ${st.lost || 0}`, `${st.passed || 0} passed · ${st.expired || 0} expired (no price shown)`)}${tile('Hit ratio', fmt.pct(st.won ? st.won / ((st.won || 0) + (st.lost || 0)) : 0, 0))}${tile('Requests received', st.requests || 0)}</div>
      <table><tr><th>ID</th><th>Client</th><th>Product</th><th>Client wants to</th><th>Detail</th><th>Mid</th><th>Street ±</th><th>Your level</th><th></th></tr>${c.open.map(r => `<tr><td>${r.id}</td><td class="l">${esc(r.client_name)}<br><span class="muted">${r.price_sensitivity} price-sensitive</span></td><td>${r.product}</td><td>${r.client_side}</td><td class="l" style="white-space:normal">${r.security_id ? `${fmt.qty(r.quantity)} ${r.security_id}` : esc(fmtParams(r.params))}</td><td>${r.unit && r.unit.startsWith('price') ? fmt.px(r.mid) : Number(r.mid).toFixed(2) + ' ' + esc(r.unit || '')}</td><td>${Number(r.street_half_width).toFixed(r.unit && r.unit.startsWith('price') ? 3 : 2)}</td><td>${r.status === 'QUOTED' ? (r.passed ? '<span class="muted">passed</span>' : lvl(r)) : `<input class="cq" data-id="${r.id}" style="width:110px" placeholder="level">`}</td><td>${r.status === 'OPEN' ? `<button class="btn cqGo" data-id="${r.id}">Quote</button> <button class="btn cqPass" data-id="${r.id}">Pass</button>` : '<span class="muted">resolves next session</span>'}</td></tr>`).join('') || '<tr><td colspan=9 class="muted">no open requests — new ones arrive each session</td></tr>'}</table>
      <p class="hint">Quote in the request's unit (a price per 100 for bonds, a price per share for blocks, a fixed rate in bp for swaps and FRAs, a spread in bp for CDS, a premium for swaptions). The client compares your level with the street: a level inside the street's half-width wins with high probability and books the trade at your price, with you on the other side. Passing keeps the relationship but not the flow.</p>
      <h2>History</h2><div class="scroll"><table><tr><th>Date</th><th>Client</th><th>Product</th><th>Side</th><th>Your level</th><th>Outcome</th><th>Note</th></tr>${c.history.map(r => `<tr><td>${r.date}</td><td class="l">${esc(r.client_name)}</td><td>${r.product}</td><td>${r.client_side}</td><td>${r.passed ? 'passed' : lvl(r)}</td><td>${statusBadge(r.outcome)}</td><td class="l" style="white-space:normal">${esc(r.note || '')}</td></tr>`).join('') || '<tr><td colspan=7 class="muted">none yet</td></tr>'}</table></div></div>`); }
    if (d.lending) { const l = d.lending;
      parts.push(`<div class="panel"><h2 style="margin-top:0">Lending desk — inventory out on loan</h2><div class="tiles">${tile('On loan (MV)', fmt.money(l.on_loan_mv, 0), `${fmt.pct(l.utilisation_of_inventory, 0)} of inventory`)}${tile('Cash collateral held', fmt.money(l.collateral_held, 0), 'reinvested at the cash rate')}${tile('Fees accrued / earned', `${fmt.money(l.accrued_fees, 0)} / ${fmt.money(l.fees_earned, 0)}`, `rebate accrued ${fmt.money(l.accrued_rebate, 0)}`)}</div>
      <div class="grid2"><div><h2>Inventory</h2><table><tr><th>Security</th><th>Held</th><th>Lent</th><th>Available</th><th>Rate</th><th>Utilisation</th><th>Annual fee if lent</th><th></th></tr>${l.inventory.map(i => `<tr><td class="l">${i.security_id}</td><td>${fmt.qty(i.held)}</td><td>${fmt.qty(i.lent)}</td><td>${fmt.qty(i.available)}</td><td>${i.rate == null ? '—' : fmt.pct(i.rate, 2)} ${i.category ? `<span class="badge ${i.category === 'GC' ? '' : 'amber'}">${i.category}</span>` : ''}</td><td>${fmt.pct(i.utilization, 0)}</td><td>${fmt.money(i.annual_fee_if_lent, 0)}</td><td>${i.available > 0 && i.rate != null ? `<input class="lq" data-id="${i.security_id}" style="width:90px" value="${i.available}"> <button class="btn lqGo" data-id="${i.security_id}">Lend</button>` : ''}</td></tr>`).join('') || '<tr><td colspan=8 class="muted">no inventory — buy securities to lend them</td></tr>'}</table></div>
      <div><h2>Loans</h2><table><tr><th>ID</th><th>Security</th><th>Qty</th><th>Borrower</th><th>Fee</th><th>Rebate</th><th>Collateral</th><th>Status</th><th></th></tr>${l.loans.slice().reverse().map(x => `<tr><td>${x.id}</td><td class="l">${x.security_id}</td><td>${fmt.qty(x.quantity)}</td><td class="l">${esc(x.borrower)}</td><td>${fmt.pct(x.rate, 2)}</td><td>${fmt.pct(x.rebate_rate, 2)}</td><td>${fmt.money(x.collateral, 0)}</td><td>${statusBadge(x.status)}${x.recall_due ? ` <span class="muted">recall due ${x.recall_due}</span>` : ''}</td><td>${x.status === 'OPEN' && !x.recall_due ? `<button class="btn lrGo" data-id="${x.id}">Recall</button>` : ''}</td></tr>`).join('') || '<tr><td colspan=9 class="muted">nothing on loan</td></tr>'}</table></div></div>
      <p class="hint">Lending pays the fee on specials and the GC rate on general collateral; you hold 102% cash collateral, pay the rebate on it and earn the cash rate. Lent shares stay yours economically (dividends are manufactured back to you) but they are encumbered: sell them and the loan is recalled for the settlement date; a borrower may also return early. Fees settle monthly.</p></div>`); }
    if (d.treasury) { const t = d.treasury;
      parts.push(`<div class="panel"><h2 style="margin-top:0">Corporate treasury</h2><div class="tiles">${tile('Liquidity', fmt.money(t.liquidity, 0), `<span class="${t.liquidity_ok ? 'pos' : 'neg'}">minimum ${fmt.money(t.min_liquidity, 0)} ${t.liquidity_ok ? '✓' : '✗ breached'}</span>`)}${tile('Debt', fmt.money(t.total_debt, 0), `floating ${fmt.money(t.floating_debt, 0)} · ${fmt.pct(t.floating_share_after_swaps, 0)} floating after swaps`)}${tile('Annual interest cost', fmt.money(t.annual_interest_cost, 0))}${Object.entries(t.fx_exposure).map(([c, x]) => tile(`${c} receipts (12m)`, fmt.money(x.next_12m_receipts_base, 0), `hedged ${fmt.pct(x.hedge_ratio, 0)} · target ${fmt.pct(t.hedge_target, 0)}`)).join('')}</div>
      <div class="grid2"><div><h2>Debt stack</h2><table><tr><th>ID</th><th>Kind</th><th>Principal</th><th>Coupon</th><th>Maturity</th></tr>${t.debt.map(x => `<tr><td>${x.id}</td><td>${x.kind}</td><td>${fmt.money(x.principal, 0)}</td><td>${x.kind === 'FIXED' ? fmt.pct(x.coupon, 2) : `policy + ${x.spread_bps}bp`}</td><td>${x.maturity}${x.retired ? ' <span class="badge">RETIRED</span>' : ''}</td></tr>`).join('')}</table><h2>Next debt events</h2>${t.next_debt_events.map(e => `<div class="mono">${e.date} ${e.debt_id} ${e.kind.toLowerCase()}</div>`).join('') || '<span class="muted">none</span>'}</div>
      <div><h2>Operating and debt flows</h2><div class="scroll"><table>${t.flows.slice().reverse().map(f => `<tr><td>${f.date}</td><td class="l">${f.kind.replace(/_/g, ' ').toLowerCase()}${f.debt_id ? ' ' + f.debt_id : ''}</td><td class="l">${(f.legs || []).map(x => `${x.currency} ${fmt.signed(x.amount, 0)}`).join(' · ')}</td><td>${fmt.signed(f.base, 0)}</td></tr>`).join('') || '<tr><td class="muted">the first operating flows arrive on the 20th</td></tr>'}</table></div><div class="hint">Next operating flow day: ${t.next_flow_day}.</div></div></div>
      <p class="hint">The company receives foreign currency every month and pays base-currency payroll and suppliers; the debt stack pays coupons (the term loan floats over the policy rate) and must be refinanced or repaid at maturity. Hedge the receipts with FX forwards (Treasury &amp; FX) or a cross-currency swap, fix the floating debt with pay-fixed swaps (OTC desk), and never let liquidity fall below the minimum.</p></div>`); }
    if (d.oversight) { const o = d.oversight;
      parts.push(`<div class="panel"><h2 style="margin-top:0">Desk oversight</h2><div class="tiles">${tile('Firm NAV', fmt.money(o.firm_nav, 0))}${tile('Firm P&L today', fmt.signed(o.firm_day_pnl, 0))}${tile('Pending requests', o.desks.reduce((a, x) => a + x.pending_requests.length, 0))}</div>
      ${o.desks.map(x => `<div class="panel" style="margin-top:8px"><h2 style="margin-top:0">${esc(x.name)} <small class="muted">${x.strategy} · NAV ${fmt.money(x.nav, 0)} · today ${fmt.signed(x.day_pnl, 0)} · gross ${fmt.money(x.gross, 0)} (${Number(x.leverage).toFixed(2)}x) · VaR99 ${x.var99 == null ? '—' : fmt.money(x.var99, 0)}</small></h2>
        ${x.limits.length ? `<div>${x.limits.map(l => `<span class="badge ${l.status === 'HARD' ? 'red' : 'amber'}">${l.status}: ${esc(l.name)} ${fmt.pct(l.value, 2)}</span>`).join(' ')}</div>` : ''}${x.breaches_today.length ? `<div>${x.breaches_today.map(b => `<span class="badge red">${b.kind}</span> ${esc(b.text)}`).join('<br>')}</div>` : ''}
        <div class="grid2"><div><h2>Requests</h2><table><tr><th>ID</th><th>Order</th><th>Notional</th><th>Why</th><th></th></tr>${x.pending_requests.map(r => `<tr><td>${r.id}</td><td class="l">${r.side} ${fmt.qty(r.quantity)} ${r.security_id}</td><td>${fmt.money(r.notional, 0)}</td><td class="l">${esc(r.note)}</td><td><button class="btn rqA" data-desk="${x.portfolio_id}" data-id="${r.id}">Approve</button> <button class="btn rqR" data-desk="${x.portfolio_id}" data-id="${r.id}">Reject</button></td></tr>`).join('') || '<tr><td colspan=5 class="muted">none pending — lapsed requests are worked in clips at the approval threshold</td></tr>'}</table>
          <h2>Limits</h2><div class="form">${['gross_mult', 'request_mult', 'var_mult'].map(k => `<label>${k.replace('_', ' ')}</label><div><input class="dl" data-desk="${x.portfolio_id}" data-key="${k}" style="width:70px" value="${x.desk_limits[k]}"> <button class="btn dlGo" data-desk="${x.portfolio_id}" data-key="${k}">Set</button></div>`).join('')}</div></div>
        <div><h2>Positions</h2><table><tr><th>Security</th><th>Qty</th><th>Value</th><th>Reduce</th></tr>${x.positions.map(p => `<tr><td class="l">${p.security_id}</td><td>${fmt.qty(p.quantity)}</td><td>${fmt.money(p.market_value, 0)}</td><td><button class="btn frGo" data-desk="${x.portfolio_id}" data-id="${p.security_id}" data-f="0.5">½</button> <button class="btn frGo" data-desk="${x.portfolio_id}" data-id="${p.security_id}" data-f="1">all</button></td></tr>`).join('') || '<tr><td colspan=4 class="muted">flat</td></tr>'}</table>${x.notes.length ? `<h2>Desk notes</h2>${x.notes.map(n => `<div class="mono muted">${n.date} ${esc(n.note)}</div>`).join('')}` : ''}</div></div></div>`).join('')}
      <p class="hint">Four rule-based desks trade through the same order, settlement, margin and risk engines as you. Orders above 8% of a desk's NAV (× its request multiplier) wait up to five sessions for your decision, then are worked in clips. gross_mult scales position sizing, var_mult scales the desk's VaR limit, and a forced reduction sends a market order on the desk's behalf. Your review is judged on the firm's breaches and drawdowns, not on P&L.</p></div>`); }
    $('#main').innerHTML = `<h1>MY DESK <small>${esc(d.title)}</small></h1>
      ${d.missions && d.missions.length ? `<div class="hint">Missions: ${d.missions.map(ms => `<span class="badge ${ms.status === 'COMPLETED' ? 'green' : ms.status === 'FAILED' ? 'red' : 'amber'}">${esc(ms.title)} ${Math.round(ms.progress * 100)}%</span>`).join(' ')} · <a href="#/portfolio/career">career →</a></div>` : ''}
      ${parts.join('') || '<div class="panel"><p class="hint">This job has no desk-specific book. The lending desk, client franchise, investor relations, corporate treasury and AI-desk oversight appear here for the jobs that carry them.</p></div>'}`;
    const post = async (path, body, ok) => { try { await api(P() + path, { method: 'POST', body }); toast(ok); render(); } catch (e) { toast(e.message, true); } };
    document.querySelectorAll('.cqGo').forEach(b => b.addEventListener('click', () => post('/desk/quote', { rfq_id: b.dataset.id, level: +$(`.cq[data-id="${b.dataset.id}"]`).value }, 'Quoted')));
    document.querySelectorAll('.cqPass').forEach(b => b.addEventListener('click', () => post('/desk/quote', { rfq_id: b.dataset.id, pass: true }, 'Passed')));
    document.querySelectorAll('.lqGo').forEach(b => b.addEventListener('click', () => post('/desk/lend', { security_id: b.dataset.id, quantity: +$(`.lq[data-id="${b.dataset.id}"]`).value }, 'Lent')));
    document.querySelectorAll('.lrGo').forEach(b => b.addEventListener('click', () => post('/desk/recall', { lend_id: b.dataset.id }, 'Recall issued')));
    document.querySelectorAll('.rqA').forEach(b => b.addEventListener('click', () => post('/desk/decide', { desk_id: b.dataset.desk, request_id: b.dataset.id, approve: true }, 'Approved')));
    document.querySelectorAll('.rqR').forEach(b => b.addEventListener('click', () => post('/desk/decide', { desk_id: b.dataset.desk, request_id: b.dataset.id, approve: false }, 'Rejected')));
    document.querySelectorAll('.dlGo').forEach(b => b.addEventListener('click', () => post('/desk/limit', { desk_id: b.dataset.desk, key: b.dataset.key, value: +$(`.dl[data-desk="${b.dataset.desk}"][data-key="${b.dataset.key}"]`).value }, 'Limit set')));
    document.querySelectorAll('.frGo').forEach(b => b.addEventListener('click', () => post('/desk/reduce', { desk_id: b.dataset.desk, security_id: b.dataset.id, fraction: +b.dataset.f }, 'Reduction ordered')));
  };

  pages.security = async (id) => {
    const s = await api(W() + `/securities/${id}?period=${state.period}`); const sec = s.security;
    if (s.is_option) { const q = s.quote || {}; $('#main').innerHTML = `<h1>${sec.id} <small>${esc(sec.name)} · ${sec.exercise_style} · ${sec.settlement_style} · ${esc(sec.exchange)} · listed ${sec.listed} · <a href="#/options/${sec.underlying}/${sec.expiry}">chain →</a> · <a href="#/security/${sec.index_level_source || sec.underlying}">underlying →</a></small></h1>
        <div class="tiles">${tile('Bid / Ask', `${fmt.px(q.bid)} / ${fmt.px(q.ask)}`, `mid ${fmt.px(q.mid)} · spread ${fmt.pct(q.spread_pct, 1)}`)}${tile('Underlying', fmt.px(s.underlying_level), `strike ${sec.strike} · ${s.days_to_expiry} days to ${sec.expiry}`)}${tile('IV', fmt.pct(q.iv, 1), `r ${fmt.pct(q.r, 2)} · q ${fmt.pct(q.q, 2)}`)}${tile('Δ / Γ', `${(q.delta || 0).toFixed(3)} / ${(q.gamma || 0).toFixed(4)}`)}${tile('Vega / Θ / ρ', `${(q.vega || 0).toFixed(3)} / ${(q.theta || 0).toFixed(3)} / ${(q.rho || 0).toFixed(4)}`, 'per share: per vol pt / day / bp')}${tile('Intrinsic + extrinsic', `${fmt.px(q.intrinsic)} + ${fmt.px(q.extrinsic)}`, q.bounds_ok ? 'within no-arbitrage bounds ✓' : 'bounds ✗')}${tile('Volume / OI', `${fmt.qty(q.volume)} / ${fmt.qty(q.open_interest)}`)}${tile('Deliverable', sec.deliverable.cash ? `cash × ${sec.index_factor}` : `${sec.deliverable.quantity} ${sec.deliverable.security_id}`, `multiplier ${sec.multiplier}`)}</div>
        <div class="grid2" style="margin-top:14px"><div class="panel"><h2 style="margin-top:0">Order ticket</h2>${ticketHtml(sec.id, false, false)}</div><div class="panel"><h2 style="margin-top:0">Today's synthetic session</h2>${s.bar ? `<div class="kv"><div>Open</div><div>${fmt.px(s.bar.open)}</div><div>High</div><div>${fmt.px(s.bar.high)}</div><div>Low</div><div>${fmt.px(s.bar.low)}</div><div>Close</div><div>${fmt.px(s.bar.close)}</div><div>Volume</div><div>${fmt.qty(s.bar.volume)}</div></div>` : '<span class="muted">expired</span>'}<p class="hint">Option session bars are derived from the underlying's open/high/low/close through the vol surface; market orders cross the spread at the open and pay impact against the contract's volume.</p>${Object.keys(s.positions).length ? `<h2>Positions</h2>${Object.entries(s.positions).map(([p, n]) => `<div class="mono">${p}: ${fmt.signed(n, 0)} contracts</div>`).join('')}` : ''}</div></div>`; bindTicket(); return; } const isBond = !!sec.coupon; const isFut = sec.asset_class === 'FUTURE'; const a = s.analytics; const f = s.fundamentals; const fu = s.futures;
    $('#main').innerHTML = `<h1>${sec.id} <small>${esc(sec.name)} · ${sec.asset_class} · ${sec.sector} · ${sec.country} · ${sec.currency} · ${isFut ? `contract month ${sec.contract_month} · cleared` : `ISIN ${sec.isin} · CUSIP ${sec.cusip} · settles ${sec.market} T+${state.world.settlement_cycles[sec.market]}`}</small></h1>
      <div class="tiles">${tile('Last', fmt.px(s.last))}${tile('Bid / Ask', `${fmt.px(s.bid)} / ${fmt.px(s.ask)}`, `spread ${fmt.bps(s.spread_bps)}`)}${tile('Volume', fmt.qty(s.volume), `ADV ${fmt.qty(sec.adv)}`)}${tile('Vol (20d realized)', fmt.pct(s.realized_vol_20d, 1))}
        ${isFut ? tile('Contract', `${fu.spec.multiplier} ${esc(fu.spec.unit)}`, `tick ${fu.spec.tick} = $${fu.spec.tick_value.toFixed(2)} · notional ${fmt.big(fu.notional_per_contract)}`) + tile('Initial margin', fmt.money(fu.initial_margin), `${fmt.pct(fu.spec.margin_pct, 0)} × regime ${fu.margin_multiplier}x`) + tile('Expiry', fu.expiry, `${fu.days_to_expiry} business days · auto-closed at expiry`) + tile('Spot / curve', fmt.px(fu.spot), `<a href="#/commodity/${sec.underlying}">${sec.underlying} desk page →</a>`)
          : isBond ? tile('YTM', fmt.pct(a.ytm, 3), `benchmark ${fmt.pct(a.benchmark_yield, 3)} · spread ${fmt.bps(a.spread_to_curve_bps)}`) + tile('Mod duration', a.modified_duration.toFixed(3), `convexity ${a.convexity.toFixed(1)}`) + tile('DV01 per $1MM', fmt.money(a.position_dv01), `dirty ${a.dirty_price.toFixed(4)} · accrued ${a.accrued.toFixed(4)}`) + tile('Rating', sec.rating, `1y PD ${fmt.pct(a.default_probability_1y, 2)} · recovery ${fmt.pct(sec.recovery_rate, 0)}`)
          : tile('Market cap', f ? fmt.big(f.market_cap) : '—', `${fmt.qty(sec.shares_outstanding)} shs`) + tile('Dividend', `$${sec.dividend_per_share}/qtr`, `yield ${fmt.pct(sec.dividend_yield, 1)}`) + tile('Beta', sec.beta, `idio vol ${fmt.pct(sec.sigma_annual, 0)}`) + tile('Borrow', 'n/a', 'securities lending: Phase 2')}
      </div>
      <div class="grid3" style="margin-top:14px"><div class="panel"><div class="row" style="justify-content:space-between"><h2 style="margin:0">Chart</h2><span class="periods">${['1D', '5D', '1M', '3M', 'YTD', '1Y', 'MAX'].map(p => `<a data-period="${p}" class="${p === state.period ? 'active' : ''}">${p}</a>`).join('')}</span></div><canvas id="px"></canvas></div>
        <div class="panel"><h2 style="margin-top:0">Order ticket</h2>${ticketHtml(sec.id, isBond, isFut)}<h2>Order book <small>${esc(s.order_book.note)}</small></h2><table class="book"><tr><th>Bid size</th><th>Bid</th><th>Ask</th><th>Ask size</th></tr>${s.order_book.levels.map(l => `<tr><td>${fmt.qty(l.bid_size)}</td><td class="bidc">${fmt.px(l.bid)}</td><td class="askc">${fmt.px(l.ask)}</td><td>${fmt.qty(l.ask_size)}</td></tr>`).join('')}</table></div></div>
      <div class="grid2" style="margin-top:14px">
        <div class="panel">${isFut ? `<h2 style="margin-top:0">${sec.underlying} futures curve</h2><canvas id="fcurve"></canvas><table style="margin-top:8px"><tr><th>Month</th><th>Price</th></tr>${Object.entries(fu.curve).map(([m, p]) => `<tr class="${m === sec.contract_month ? 'pos' : ''}"><td>${m}</td><td>${fmt.px(p)}</td></tr>`).join('')}</table>` : isBond ? `<h2 style="margin-top:0">Cash flows (per 100 face)</h2><table><tr><th>Date</th><th>Amount</th></tr>${s.cash_flows.map(c => `<tr><td>${c[0]}</td><td>${c[1].toFixed(4)}</td></tr>`).join('')}</table>`
          : f ? `<h2 style="margin-top:0">Fundamentals</h2><div class="kv"><div>Revenue</div><div>${fmt.big(f.revenue)}</div><div>EBITDA</div><div>${fmt.big(f.ebitda)}</div><div>Net income</div><div>${fmt.big(f.net_income)}</div><div>EPS</div><div>${f.eps}</div><div>Free cash flow</div><div>${fmt.big(f.free_cash_flow)}</div><div>Total debt</div><div>${fmt.big(f.total_debt)}</div><div>Cash</div><div>${fmt.big(f.cash)}</div><div>Enterprise value</div><div>${fmt.big(f.enterprise_value)}</div><div>P/E</div><div>${f.pe ? f.pe.toFixed(1) : '—'}</div><div>EV/EBITDA</div><div>${f.ev_ebitda ? f.ev_ebitda.toFixed(1) : '—'}</div><div>P/B</div><div>${f.pb ? f.pb.toFixed(2) : '—'}</div><div>FCF yield</div><div>${fmt.pct(f.fcf_yield)}</div><div>Debt/EBITDA</div><div>${f.debt_ebitda ? f.debt_ebitda.toFixed(2) : '—'}</div><div>ROE</div><div>${fmt.pct(f.roe)}</div></div>` : '<p class="muted mono">no issuer fundamentals (fund/ETF)</p>'}</div>
        <div class="panel"><h2 style="margin-top:0">Corporate actions</h2><table><tr><th>ID</th><th>Type</th><th>Declared</th><th>Ex</th><th>Record</th><th>Pay</th><th>Amount</th><th>Status</th></tr>${s.corporate_actions.map(c => `<tr><td class="l">${c.id}</td><td class="l">${c.action_type}</td><td>${c.declared_date}</td><td>${c.ex_date}</td><td>${c.record_date}</td><td>${c.pay_date}</td><td>${c.amount_per_unit}</td><td>${statusBadge(c.status)}</td></tr>`).join('') || '<tr><td colspan=8 class="muted">none scheduled</td></tr>'}</table>
          <h2>News</h2>${s.news.map(n => `<div class="mono" style="margin-bottom:6px"><span class="muted">${n.date}</span> ${esc(n.headline)}</div>`).join('') || '<p class="muted mono">no news</p>'}</div></div>`;
    candleChart($('#px'), s.bars);
    if (isFut) lineChart($('#fcurve'), [{ data: Object.values(fu.curve), color: css('--accent'), dots: true }], { labels: Object.keys(fu.curve).map(m => m.slice(2)), fmtY: v => v.toFixed(2), h: 160 });
    document.querySelectorAll('[data-period]').forEach(a => a.addEventListener('click', () => { state.period = a.dataset.period; render(); }));
    bindTicket();
  };

  function ticketHtml(secId = '', isBond = false, isFuture = false) {
    return `<div class="form" id="ticket"><label>Security</label><input id="tSec" value="${secId}" placeholder="ticker, bond id or contract e.g. NVDA, UST-10Y, CLZ26" ${secId ? 'readonly' : ''}><label>Side</label><select id="tSide"><option>BUY</option><option>SELL</option></select>
      <label>Quantity</label><div class="row"><input id="tQty" type="number" value="${isFuture ? prefs.trading.fut_qty : isBond ? prefs.trading.bond_qty : prefs.trading.qty}" step="${isBond ? 1000 : 'any'}" style="width:140px"><span class="muted mono">or amount $</span><input id="tAmt" type="number" step="1000" placeholder="e.g. 250000" style="width:140px"></div>
      <label></label><div id="tEst" class="hint" style="margin:0">enter a security and quantity to see the cash involved</div>${liveOn() ? `<label>Execute</label><select id="tExec"><option value="LIVE">NOW — at the live quote (Yahoo, up to 15 min delayed)</option><option value="NEXT_UPDATE">NEXT UPDATE — an instruction against the session</option></select>` : ''}<label>Type</label><select id="tType"><option value="MARKET">MARKET</option><option value="LIMIT">LIMIT</option><option value="STOP">STOP</option><option value="STOP_LIMIT">STOP_LIMIT</option><option value="TAKE_PROFIT">TAKE_PROFIT</option><option value="TRAILING_STOP">TRAILING_STOP</option></select>
      <label>Limit</label><input id="tLimit" type="number" step="0.0001" placeholder="limit price"><label>Stop</label><input id="tStop" type="number" step="0.0001" placeholder="stop price"><label>Trail %</label><input id="tTrail" type="number" step="0.1" placeholder="e.g. 5 = 5% below best close">
      <label>Condition</label><div class="row"><span class="muted mono">only if</span><input id="tCondRef" placeholder="NVDA · CURVE:10Y · SPOT:CL" style="width:150px"><select id="tCondOp"><option>&lt;=</option><option>&gt;=</option></select><input id="tCondVal" type="number" step="any" placeholder="value" style="width:110px"></div>
      <label>TIF</label><select id="tTif"><option value="DAY">DAY — good for the next session</option><option value="GTC">GTC — until cancelled</option></select><label>#Tag</label><input id="tTag" placeholder="optional · groups this trade with others on every desk, e.g. crack-spread" value="${prefs.trading.tag || ''}">
      <label>Settle in</label><div class="row"><select id="tCcy">${CCYS.map(c => `<option ${c === (prefs.trading.ccy || 'USD') ? 'selected' : ''}>${c}</option>`).join('')}</select><span id="tCcyNote" class="muted mono" style="font-size:11px">the currency that pays for a buy or receives a sale; another currency is converted at spot (T+2)</span></div></div>
      <div class="row" style="margin-top:8px"><button class="btn primary" id="tGo">Submit instruction</button><span id="tMsg" class="mono"></span></div><p class="hint">${liveOn() ? '<b>Now</b>: a market order fills immediately at the latest real quote (Yahoo Finance, up to 15 minutes delayed; bonds use the last close) with the usual spread, impact and commission, any hour of any day; a limit, stop, stop-limit, take-profit or trailing stop <b>rests against the live quote</b> and fills the moment a refresh finds the quote has reached it (every minute, whether or not a page is open), and the daily update evaluates it against the session too. <b>Next update</b> sends an instruction: it executes at the next session\'s open, or at its close if that session is already running, so an open you can already see is never yours. ' : 'Instructions execute at the next daily update against that session (open, high, low, close, volume). '}${isFuture ? 'Futures: quantity is contracts; shorts allowed; initial margin is posted from cash and P&L settles daily as variation margin.' : isBond ? 'Bond quantity is face value (multiples of 1,000). Price is clean per 100; accrued interest is paid on top.' : 'Market orders cross the spread and pay impact. Orders above 20% of session volume fill partially and keep working (GTC) or expire (DAY).'} Conditions are checked at the close (yields in %, e.g. CURVE:10Y >= 5).</p>`;
  }
  function bindTicket() {
    const go = $('#tGo'); if (!go) return;
    if ($('#tType')) $('#tType').value = prefs.trading.type; if ($('#tTif')) $('#tTif').value = prefs.trading.tif;
    const execOf = () => ($('#tExec') ? $('#tExec').value : 'NEXT_UPDATE');
    const syncExec = () => { const live = execOf() === 'LIVE'; const t = $('#tType'); if (!t) return; go.textContent = live ? (t.value === 'MARKET' ? 'Execute now' : 'Work live') : 'Submit instruction'; ['tCondRef', 'tCondOp', 'tCondVal'].forEach(id => { const el = $('#' + id); if (el) { el.disabled = live; el.title = live ? 'a conditional order is an instruction for the daily update' : ''; } }); };
    if ($('#tExec')) { $('#tExec').value = prefs.trading.exec || 'LIVE'; $('#tExec').addEventListener('change', () => { syncExec(); arm(false); }); }
    if ($('#tType')) $('#tType').addEventListener('change', syncExec);
    // live cash estimate: quantity -> cash, or cash amount -> quantity
    let estTimer = null, fromAmount = false;
    const estimate = async () => {
      const sid = $('#tSec').value.trim().toUpperCase(); const est = $('#tEst'); if (!sid || !est) return;
      const body = { security_id: sid, side: $('#tSide').value, limit_price: $('#tLimit').value ? +$('#tLimit').value : null, settle_ccy: ($('#tCcy') || {}).value || undefined, execution: execOf() };
      if (fromAmount && $('#tAmt').value) body.amount = +$('#tAmt').value; else body.quantity = +$('#tQty').value;
      try {
        const p = await api(P() + '/orders/preview', { method: 'POST', body });
        if (fromAmount && $('#tAmt').value) $('#tQty').value = p.quantity;
        const unit = p.kind === 'bond' ? 'face' : p.kind === 'future' || p.kind === 'option' ? 'contract(s)' : p.kind === 'crypto' ? 'coin(s)' : 'share(s)';
        const cash = Number(p.cash_needed);
        const main = p.kind === 'future'
          ? `${fmt.qty(p.quantity)} ${unit} × ${fmt.px(p.price)} × ${p.multiplier} = notional <b>${fmt.money(p.gross, 0)}</b> · initial margin <b>${fmt.money(p.initial_margin, 0)}</b> + commission ${fmt.money(p.commission)}`
          : `${fmt.qty(p.quantity)} ${unit} × ${fmt.px(p.price)}${p.multiplier !== 1 ? ` × ${p.multiplier}` : ''}${p.kind === 'bond' ? ' / 100' : ''} = <b>${fmt.money(p.gross)}</b>${Number(p.accrued_interest) ? ` + accrued ${fmt.money(p.accrued_interest)}` : ''} ${p.side === 'BUY' ? '+' : '−'} commission ${fmt.money(p.commission)}`;
        const fxLine = p.fx ? ` <span class="ccyline">→ ${p.fx.direction === 'pay' ? `paid with <b>${p.settle_ccy} ${fmt.money(p.fx.settle_amount)}</b> (spot ${Number(p.fx.rate) >= 20 ? Number(p.fx.rate).toFixed(2) : Number(p.fx.rate).toFixed(4)} + ${Number(p.fx.spread_bps).toFixed(1)}bp, dealt now, settles T+2; ${p.settle_ccy} balance ${fmt.money(p.fx.settle_balance, 0)})` : `received in <b>${p.settle_ccy} ${fmt.money(p.fx.settle_amount)}</b> (spot ${Number(p.fx.rate) >= 20 ? Number(p.fx.rate).toFixed(2) : Number(p.fx.rate).toFixed(4)}, dealt now against the proceeds)`}</span>` : '';
        const cb = p.cash_by_currency || {}; const cn = $('#tCcyNote'); if (cn) cn.innerHTML = Object.entries(cb).filter(([c, a]) => Number(a.settled) !== 0 || c === 'USD').map(([c, a]) => `${c} ${fmt.money(a.settled, 0)}`).join(' · ') || 'cash balances by currency';
        const liveL = p.live ? `<div class="liveline">live ${liveLine(p.live)}${p.live.age_s != null ? ` <span class="muted" style="font-size:10px">(${liveAge(p.live)})</span>` : ''} · fills ${execLabel('LIVE')}</div>` : (execOf() === 'NEXT_UPDATE' && liveOn() ? `<div class="liveline muted">instruction: fills ${execLabel('NEXT_UPDATE')} · shown at the last close</div>` : '');
        est.innerHTML = `${liveL}${main} → <b class="${cash > 0 ? 'neg' : 'pos'}">${cash > 0 ? 'pay' : 'receive'} ${p.currency} ${fmt.money(Math.abs(cash))}</b> at ${p.price_source}${fxLine} <span class="muted">· settled ${p.currency} ${fmt.money(p.cash_settled, 0)}, projected ${fmt.money(p.cash_projected, 0)}${!p.fx && cash > Number(p.cash_projected) ? ' — exceeds projected cash (prime-broker financing or rejection)' : ''}</span>`;
      } catch (e) { est.innerHTML = `<span class="muted">${esc(e.message)}</span>`; }
    };
    const arm = (viaAmount) => { fromAmount = viaAmount; clearTimeout(estTimer); estTimer = setTimeout(estimate, 250); };
    ['tSec', 'tQty', 'tSide', 'tLimit', 'tCcy'].forEach(id => { const el = $('#' + id); if (el) el.addEventListener('input', () => arm(false)); if (el) el.addEventListener('change', () => arm(false)); });
    if ($('#tAmt')) $('#tAmt').addEventListener('input', () => arm(true));
    if ($('#tSec').value) arm(false);
    syncExec();
    go.addEventListener('click', async () => {
      const cond = $('#tCondRef').value.trim() ? { ref: $('#tCondRef').value.trim(), op: $('#tCondOp').value.replace('&lt;', '<').replace('&gt;', '>'), value: +$('#tCondVal').value } : null;
      if ($('#tAmt').value && !(+$('#tQty').value)) { try { const p = await api(P() + '/orders/preview', { method: 'POST', body: { security_id: $('#tSec').value.trim().toUpperCase(), side: $('#tSide').value, amount: +$('#tAmt').value, limit_price: $('#tLimit').value ? +$('#tLimit').value : null } }); $('#tQty').value = p.quantity; } catch (e) {} }
      const body = { security_id: $('#tSec').value.trim().toUpperCase(), side: $('#tSide').value, quantity: +$('#tQty').value, order_type: $('#tType').value, limit_price: $('#tLimit').value ? +$('#tLimit').value : null, stop_price: $('#tStop').value ? +$('#tStop').value : null, time_in_force: $('#tTif').value, strategy_tag: $('#tTag').value || null, trail_pct: $('#tTrail').value ? +$('#tTrail').value / 100 : null, condition: cond, settle_ccy: ($('#tCcy') || {}).value || null, execution: execOf() };
      go.disabled = true; $('#tMsg').textContent = '';
      try { const r = await api(P() + '/orders', { method: 'POST', body }); toast(orderToast(r)); render(); }
      catch (e) { $('#tMsg').innerHTML = `<span class="error">${esc(e.message)}</span>`; } finally { go.disabled = false; }
    });
  }
  function ordersTable(orders) {
    // cancelled, expired and rejected instructions leave the blotter (a toggle brings them back); filled ones stay as the record
    const done = o => ['CANCELLED', 'EXPIRED', 'REJECTED'].includes(o.status);
    const hidden = orders.filter(done).length; const rows = state.showDone ? orders : orders.filter(o => !done(o));
    const typeText = o => `${o.order_type.replace(/_/g, ' ')}${o.limit_price ? ' @ ' + fmt.px(o.limit_price) : ''}${o.stop_price ? ' stop ' + fmt.px(o.stop_price) : ''}${o.trail_level ? ` trail ${fmt.px(o.trail_level)} (${(o.trail_pct * 100).toFixed(1)}%)` : ''}${o.condition ? ` if ${o.condition.ref} ${o.condition.op} ${o.condition.value}${o.condition_met_date ? ' ✓' : ''}` : ''}${o.strategy_tag === 'SYSTEM' ? ' <span class="badge">SYSTEM</span>' : o.strategy_tag ? ` <span class="muted">#${esc(o.strategy_tag)}</span>` : ''}${o.execution === 'LIVE' ? ` <span class="badge green" title="works against the live quote: checked every minute and at the daily update">LIVE</span>` : ''}`;
    return `<div class="scroll"><table><tr><th>Order</th><th>Entered</th><th>Security</th><th>Side</th><th>Qty</th><th>Type</th><th>Filled</th><th>Avg px</th><th>TIF</th><th>Status</th><th></th><th>Latest</th></tr>
      ${rows.map(o => `<tr><td>${o.id}</td><td>${o.entered_date}</td><td><a href="#/security/${o.security_id}">${o.security_id}</a></td><td class="${o.side === 'BUY' ? 'pos' : 'neg'}">${o.side}</td><td>${fmt.qty(o.quantity)}</td><td class="l">${typeText(o)}</td><td>${o.filled_quantity ? fmt.qty(o.filled_quantity) : '—'}</td><td>${o.filled_quantity ? fmt.px(o.avg_fill_price) : '—'}</td><td>${o.time_in_force}</td><td>${statusBadge(o.status)}</td><td>${['WORKING', 'PARTIALLY_FILLED'].includes(o.status) ? `<button class="btn danger" data-cancel="${o.id}">cancel</button>` : ''}</td><td class="l muted" style="max-width:260px;overflow:hidden;text-overflow:ellipsis" title="${esc(o.reason || '')}">${esc(o.reason || '')}</td></tr>`).join('') || `<tr><td colspan=12 class="muted">${orders.length ? 'no live or filled instructions' : 'no instructions yet'}</td></tr>`}</table></div>
      ${hidden ? `<div class="hint" style="margin-top:4px"><a data-toggle-done>${state.showDone ? 'hide' : 'show'} ${hidden} cancelled / expired / rejected</a></div>` : ''}`;
  }
  function tradesTable(trades) {
    return `<div class="scroll"><table><tr><th>Trade</th><th>T date</th><th>S date</th><th>Security</th><th>Side</th><th>Qty</th><th>Price</th><th>Gross</th><th>Accrued</th><th>Comm</th><th>Net</th><th>Realized</th><th>Impact</th><th>Status</th></tr>
      ${trades.map(t => `<tr class="click" data-trade="${t.id}"><td>${t.id}</td><td>${t.trade_date}</td><td>${t.settlement_date}</td><td>${t.security_id}</td><td class="${t.side === 'BUY' ? 'pos' : 'neg'}">${t.side}</td><td>${fmt.qty(t.quantity)}</td><td>${fmt.px(t.price)}</td><td>${fmt.money(t.gross_amount)}</td><td>${fmt.money(t.accrued_interest)}</td><td>${fmt.money(t.commission)}</td><td>${fmt.money(t.net_amount)}</td><td>${t.side === 'SELL' ? fmt.signed(t.realized_pnl) : '—'}</td><td>${fmt.bps(t.execution_detail.impact_bps)}</td><td>${statusBadge(t.status)}</td></tr>`).join('') || '<tr><td colspan=14 class="muted">no trades</td></tr>'}</table></div>`;
  }
  function entriesTable(entries) {
    return `<table><tr><th>Entry</th><th>Date</th><th>Memo</th><th>Account</th><th>Debit</th><th>Credit</th><th>Security</th><th>Event</th></tr>
      ${entries.map(e => e.lines.map((l, i) => `<tr>${i === 0 ? `<td rowspan="${e.lines.length}">${e.id}</td><td rowspan="${e.lines.length}">${e.date}</td><td rowspan="${e.lines.length}" class="l" style="white-space:normal;max-width:340px">${esc(e.memo)}</td>` : ''}<td class="l">${l.account} <span class="muted">${esc(l.name)}</span></td><td>${l.debit ? fmt.money(l.debit) : ''}</td><td>${l.credit ? fmt.money(l.credit) : ''}</td><td>${l.security_id || ''}</td>${i === 0 ? `<td rowspan="${e.lines.length}"><a data-event="${e.cause_id || e.event_id}">${e.cause_id || e.event_id}</a></td>` : ''}</tr>`).join('')).join('') || '<tr><td colspan=8 class="muted">no entries</td></tr>'}</table>`;
  }
  const LIFECYCLE = ['EXECUTED', 'CAPTURED', 'MATCHED', 'AFFIRMED', 'CLEARED', 'SETTLEMENT_PENDING', 'SETTLED'];
  async function tradeModal(id) {
    const x = await api(P() + '/trades/' + id); const t = x.trade, si = x.settlement, ed = t.execution_detail; const reached = new Set(t.status_history.map(h => h.status));
    modal(`<h1>Trade ${t.id} <a onclick="document.getElementById('modalRoot').innerHTML=''">✕</a></h1>
      <div class="lifecycle">${LIFECYCLE.map(s => `<span class="${t.status === 'FAILED' && s === 'SETTLED' ? 'fail' : reached.has(s) ? (s === t.status ? 'cur' : 'done') : ''}">${s}</span>`).join('')}${t.status === 'FAILED' ? '<span class="fail">FAILED (retrying)</span>' : ''}</div>
      <div class="grid2"><div><h2>Economics</h2><div class="kv"><div>Security</div><div><a href="#/security/${t.security_id}" onclick="document.getElementById('modalRoot').innerHTML=''">${t.security_id}</a></div><div>Side / qty</div><div>${t.side} ${fmt.qty(t.quantity)}</div><div>Price</div><div>${fmt.px(t.price)}</div><div>Gross</div><div>${fmt.money(t.gross_amount)}</div><div>Accrued interest</div><div>${fmt.money(t.accrued_interest)}</div><div>Commission</div><div>${fmt.money(t.commission)}</div><div>Net ${t.side === 'BUY' ? 'payable' : 'receivable'}</div><div>${fmt.money(t.net_amount)} ${t.currency}</div><div>Trade / settle</div><div>${t.trade_date} → ${t.settlement_date}</div><div>Broker</div><div>${esc(t.broker)}</div>${t.side === 'SELL' ? `<div>Realized P&L</div><div>${fmt.signed(t.realized_pnl)}</div>` : ''}</div>
        <h2>Execution quality</h2><div class="kv"><div>Session</div><div>${ed.session} (${ed.regime})</div><div>Session O/H/L/C</div><div>${fmt.px(ed.reference_open)} / ${fmt.px(ed.reference_high)} / ${fmt.px(ed.reference_low)} / ${fmt.px(ed.reference_close)}</div><div>Base price</div><div>${fmt.px(ed.base_price)}</div><div>Spread cost</div><div>${fmt.money(ed.spread_cost)}</div><div>Impact</div><div>${fmt.money(ed.impact_cost)} (${fmt.bps(ed.impact_bps)})</div><div>Participation of ADV</div><div>${fmt.pct(ed.participation_of_adv)}</div><div>Partial</div><div>${ed.partial ? 'yes — remainder works' : 'no'}</div>${ed.forced ? `<div>Forced</div><div class="neg">${esc(ed.note)}</div>` : ed.note ? `<div>Note</div><div>${esc(ed.note)}</div>` : ''}</div>
        ${t.lots_relieved && t.lots_relieved.length ? `<h2>Lots relieved (FIFO)</h2><table><tr><th>Lot</th><th>Opened</th><th>Qty</th><th>Cost/unit</th><th>Cost</th></tr>${t.lots_relieved.map(l => `<tr><td>${l.lot_id}</td><td>${l.open_date}</td><td>${fmt.qty(l.quantity)}</td><td>${fmt.px(l.cost_per_unit)}</td><td>${fmt.money(l.cost)}</td></tr>`).join('')}</table>` : ''}</div>
      <div><h2>Status history</h2><table><tr><th>Date</th><th>Status</th><th>Note</th><th>Event</th></tr>${t.status_history.map(h => `<tr><td>${h.date}</td><td class="l">${statusBadge(h.status)}</td><td class="l" style="white-space:normal">${esc(h.note)}</td><td><a data-event="${h.event_id}">${h.event_id}</a></td></tr>`).join('')}</table>
        ${!si && t.status === 'CLEARED' ? '<h2>Clearing</h2><div class="kv"><div>Type</div><div>Cleared futures — no DVP; margined daily</div></div>' : ''}
        ${si ? `<h2>Settlement instruction ${si.id}</h2><div class="kv"><div>Type</div><div>${si.instruction_type} (${si.instruction_type === 'RVP' ? 'receive vs payment' : 'deliver vs payment'})</div><div>Deliverer → receiver</div><div>${esc(si.delivering_party)} → ${esc(si.receiving_party)}</div><div>Custodian</div><div>${esc(si.custodian)}</div><div>Status</div><div>${statusBadge(si.status)} ${si.fail_count ? `<span class="error">${si.fail_count} fail(s): ${esc(si.fail_reason)}</span>` : ''}</div><div>Settled</div><div>${si.settled_date || '—'}</div></div>` : ''}</div></div>
      <h2>Ledger entries</h2>${entriesTable(x.ledger_entries)}
      <h2>Events</h2><table><tr><th>Event</th><th>Type</th><th>Date</th><th>Cause</th></tr>${x.events.map(e => `<tr><td><a data-event="${e.id}">${e.id}</a></td><td class="l">${e.type}</td><td>${e.sim_date}</td><td>${e.cause_id || ''}</td></tr>`).join('')}</table>`);
    bindRows();
  }
