  async function pagePerformance() {
    const [d, yc] = await Promise.all([api(P() + '/dashboard'), api(W() + '/yield-curve')]);
    const navs = d.nav_history; const bid = d.benchmark ? d.benchmark.id : null;
    const bench = bid ? await api(W() + `/securities/${bid}?period=MAX`).catch(() => null) : null;
    let bser = null;
    if (bench && bench.bars && bench.bars.length) { const bmap = {}; bench.bars.forEach(b => { bmap[b[0]] = b[4]; }); let last = null; bser = navs.map(v => { if (bmap[v.date] != null) last = bmap[v.date]; return last; }); const first = bser.find(v => v != null); bser = bser.map(v => v == null ? first : v); }
    const st = perfStats(navs, bser, yc.policy_rate);
    let peak = 0; const dd = navs.map(v => { peak = Math.max(peak, Number(v.nav)); return peak ? Number(v.nav) / peak - 1 : 0; });
    const months = {}; navs.forEach((v, i) => { const m = v.date.slice(0, 7); if (!months[m]) months[m] = { first: i ? Number(navs[i - 1].nav) : Number(v.nav), last: Number(v.nav), b0: bser ? (i ? bser[i - 1] : bser[i]) : null, b1: bser ? bser[i] : null }; else { months[m].last = Number(v.nav); if (bser) months[m].b1 = bser[i]; } });
    const f2 = v => v == null ? '—' : Number(v).toFixed(2);
    $('#main').innerHTML = `<h1>PERFORMANCE <small>${navs.length} sessions${bid ? ` · benchmark ${bid}` : ''} · risk-free = policy rate ${fmt.pct(yc.policy_rate)}</small></h1>
      ${st ? `<div class="tiles">${tile('Total return', fmt.pct(st.total), st.days >= 60 ? `annualised ${fmt.pct(st.ann)}` : `${st.days} sessions — too few to annualise`)}${tile('Volatility', fmt.pct(st.vol, 1), 'annualised, daily returns')}${tile(gl('Sharpe ratio', 'Sharpe'), f2(st.sharpe), `Sortino ${f2(st.sortino)}`)}${tile(gl('Maximum drawdown', 'Max drawdown'), fmt.pct(st.mdd, 1), `current ${fmt.pct(dd[dd.length - 1], 1)}`)}${tile('Hit rate', fmt.pct(st.wins, 0), `best ${fmt.pct(st.best)} · worst ${fmt.pct(st.worst)}`)}${st.benchTotal != null ? tile(`vs ${bid}`, fmt.pct(st.total - st.benchTotal), `${bid} ${fmt.pct(st.benchTotal)}`) + tile(gl('Beta', 'Beta / correlation'), `${f2(st.beta)} / ${f2(st.corr)}`, 'to the benchmark, daily') + tile(gl('Alpha', 'Alpha (annualised)'), fmt.pct(st.alpha), 'CAPM, vs the benchmark') : ''}</div>` : '<p class="muted mono">fewer than two sessions — nothing to measure yet</p>'}
      <div class="grid2" style="margin-top:14px"><div class="panel"><h2 style="margin-top:0">Growth of 100 <span class="legend"><i style="background:${css('--accent')}"></i>book${bid ? ` <i style="background:${css('--blue')}"></i>${bid}` : ''}</span></h2><canvas id="growth"></canvas><h2>Drawdown</h2><canvas id="ddChart"></canvas></div>
        <div class="panel"><h2 style="margin-top:0">Monthly returns</h2><table><tr><th>Month</th><th>Book</th>${bid ? `<th>${bid}</th><th>Excess</th>` : ''}</tr>${Object.entries(months).reverse().map(([m, v]) => { const r = v.first ? v.last / v.first - 1 : 0; const b = v.b0 && v.b1 ? v.b1 / v.b0 - 1 : null; return `<tr><td>${m}</td><td class="${r >= 0 ? 'pos' : 'neg'}">${fmt.pct(r)}</td>${bid ? `<td>${b == null ? '—' : fmt.pct(b)}</td><td class="${b != null && r - b >= 0 ? 'pos' : 'neg'}">${b == null ? '—' : fmt.pct(r - b)}</td>` : ''}</tr>`; }).join('')}</table>
          <p class="hint">Returns are NAV to NAV (capital flows distort them in the month they land). Sharpe and Sortino use daily returns annualised by √252 against the policy rate; alpha and beta come from a daily regression on the benchmark's closes. The career tab holds the reviews that grade you on these.</p></div></div>`;
    const base = Number(navs[0] ? navs[0].nav : 1); const series = [{ data: navs.map(v => Number(v.nav) / base * 100), color: css('--accent') }];
    if (bser) series.push({ data: bser.map(v => v / bser[0] * 100), color: css('--blue') });
    lineChart($('#growth'), series, { labels: navs.map(v => v.date.slice(5)), fmtY: v => v.toFixed(1), h: 220 });
    lineChart($('#ddChart'), [{ data: dd.map(v => v * 100), color: css('--red') }], { labels: navs.map(v => v.date.slice(5)), fmtY: v => v.toFixed(1) + '%', zero: true, h: 140 });
  }

