    $('#posCsvAll').addEventListener('click', () => download(`finsim-positions-${state.world.current_date}.csv`, shown.map(s => `${s.title}\n${XL.csv(s.cols, s.rows)}`).join('\n\n')));
    const inp = $('#posQ'); inp.addEventListener('input', () => { state.posQ = inp.value; clearTimeout(state._posT); state._posT = setTimeout(() => { const pos = inp.selectionStart; render().then(() => { const i2 = $('#posQ'); if (i2) { i2.focus(); i2.setSelectionRange(pos, pos); } }); }, 250); });
