        <div class="row" style="gap:6px;margin-bottom:8px;flex-wrap:wrap">${filterHtml('filter by ticker, name, sector…')}<select id="mkSector"><option value="">all sectors</option>${sectors.map(s => `<option ${s === f.sector ? 'selected' : ''}>${s}</option>`).join('')}</select><select id="mkCls"><option value="">all classes</option>${classes.map(c => `<option value="${c}" ${c === f.cls ? 'selected' : ''}>${CLASS_LABEL[c] || c}</option>`).join('')}</select><select id="mkSort">${[['id', 'A → Z'], ['cap', 'largest first'], ['chg', 'top gainers'], ['loss', 'top losers'], ['vol', 'most traded ($)'], ['yld', 'highest yield'], ['rv', 'most volatile']].map(([k, l]) => `<option value="${k}" ${k === f.sort ? 'selected' : ''}>${l}</option>`).join('')}</select><span class="muted mono">${rows.length} shown · click a row to load it into the ticket</span></div>
